    '''
    
    PendingCalculation: Optional[PendingCalculation] = field(
        default=None,
        metadata={
        'type': 'Association',
        'stereotypes': [],
        'minOccurs': '0',
        'maxOccurs': '1',
        'inverse': 'PendingCalculation.IntervalBlocks',
        'namespace': 'http://iec.ch/TC57/CIM100#',
        'serialize': True,
        })
    '''
